widget.prelude:
import numpy as np

words = open('names.txt').read().splitlines()
perm = np.random.default_rng(42).permutation(len(words))
train = [words[i] for i in perm[:25626]]
dev = [words[i] for i in perm[25626:28829]]
INDEX = {c: i for i, c in enumerate(".abcdefghijklmnopqrstuvwxyz")}


def build_dataset(ws, block=3):
    X, Y = [], []
    for w in ws:
        context = [0] * block
        for ch in w + ".":
            X.append(context)
            Y.append(INDEX[ch])
            context = context[1:] + [INDEX[ch]]
    return np.array(X), np.array(Y)


def course_init():
    g = np.random.default_rng(0)
    return {"C": g.standard_normal((27, 10)), "W1": g.standard_normal((30, 100)) * (5 / 3) / np.sqrt(30),
            "b1": np.zeros(100), "W2": g.standard_normal((100, 27)) * 0.01, "b2": np.zeros(27)}


def full_loss(p, X, Y):
    E = p["C"][X].reshape(len(X), -1)
    Z = np.tanh(E @ p["W1"] + p["b1"]) @ p["W2"] + p["b2"]
    m = Z.max(axis=1, keepdims=True)
    return float((np.log(np.exp(Z - m).sum(axis=1)) + m[:, 0] - Z[np.arange(len(Y)), Y]).mean())


def train_mlp(p, X, Y, steps, lr, seed):
    # level 2's loop, written out in NumPy; returns the trained parameters
    p = {k: v.copy() for k, v in p.items()}
    rng = np.random.default_rng(seed)
    for _ in range(steps):
        ix = rng.integers(0, len(X), 32)
        x, y = X[ix], Y[ix]
        E = p["C"][x].reshape(32, -1)
        h = np.tanh(E @ p["W1"] + p["b1"])
        Z = h @ p["W2"] + p["b2"]
        P = np.exp(Z - Z.max(axis=1, keepdims=True))
        P /= P.sum(axis=1, keepdims=True)
        P[np.arange(32), y] -= 1
        dZ = P / 32
        dpre = (dZ @ p["W2"].T) * (1 - h ** 2)
        dE = (dpre @ p["W1"].T).reshape(32, x.shape[1], -1)
        dC = np.zeros_like(p["C"])
        np.add.at(dC, x, dE)
        grads = {"C": dC, "W1": E.T @ dpre, "b1": dpre.sum(0), "W2": h.T @ dZ, "b2": dZ.sum(0)}
        for k in p:
            p[k] -= lr * grads[k]
    return p

